BASE_FIELDS=['id','name','value','unit','period','status','qualifier']
def add(cid,title,primitive,mode,scale,geometry,color,backside,legend,extra=(),special=(),**kw):
    OVERRIDES[cid]={'title':title,'primitive':primitive,'mode':mode,'fields':BASE_FIELDS+list(extra),'scale':scale,'geometry':geometry,'color':color,'backside':backside,'legend':legend,'special':list(special),**kw}
# Revised primary-source extracts: preserve the measured denominator and uncertainty.
OVERRIDES['422-2']['geometry']='Four equal meridian lanes use labelled semicircles: 0% at the start and 100% at the opposite end, arc angle=pi*value/100. Female- and male-dominated occupations are paired within exposureCategory. High exposure combines gradients3–4 and is a subset of any exposure; never add categories.'
OVERRIDES['422-2']['backside']='The any-exposure pair begins in front; rotating half a turn exposes the high-exposure(gradients3–4) pair. Next comparison reaches the same rows without dragging.'
OVERRIDES['422-2']['special']=['Require four rows and correct exposureCategory labels.','High exposure combines gradients3–4 and is contained within any exposure.','100% must occupy the whole labelled semicircle, not be mistaken for half of a full circle.','Occupation shares are not individual worker shares or job-loss observations.']
OVERRIDES['330']['fields']+=['standardError','regressionN']
OVERRIDES['330']['geometry']='Two independent tangent gauges show English and composite intention-to-treat coefficients on a common0–0.4SD rail. Position=value/0.4. Whiskers use value±standardError and are labelled ±1 robust SE, not95%CI. Both outcomes arise from one teacher-supported intervention.'
OVERRIDES['330']['legend']='Estimated ITT effects, June–July2024 intervention in sampled Edo State schools. Whiskers: ±1 robust standard error; regressionN654. Not a national effect.'
OVERRIDES['330']['special']=['Exact table values: English0.238, composite0.310, robustSE0.068 each, regressionN654.','Never draw a Nigeria-wide filled polygon.','Whiskers are ±1SE; do not relabel as a95%confidence interval.']
OVERRIDES['320']['fields']+=['timeBasis']
OVERRIDES['320']['scale']={'type':'linear','domain':[0,10],'unit':'USD per hour'}
OVERRIDES['320']['geometry']='Four constant-size plates on0–10USD/hour rails pair mean and median within each timeBasis. Height=value/10. A Paid hours only / Include unpaid time switch brings one pair forward while preserving the other as a labelled outline; values never interpolate as a historical change.'
OVERRIDES['320']['backside']='Turn the assembly to reveal the paid-hours-only pair, then inspect how including unpaid search/admin time changes the denominator. Mean and median remain different statistics, not worker groups.'
OVERRIDES['320']['legend']='Surveyed LAC web-platform workers,15December2023–31March2024. Time denominator changes hourly pay; not AI-only labour.'
